#include <stdio.h>
#include <stdlib.h>
int main() {
    int staticArray[5] = {1, 2, 3, 4, 5};  // Static allocation for fixed data
    int* dynamicArray = (int*)malloc(5 * sizeof(int));  // Dynamic allocation
    if (dynamicArray == NULL) {
        printf("Allocation failed\n");
        return 1;
    }
    for(int i = 0; i < 5; i++) {
        dynamicArray[i] = staticArray[i] * 2;  // Combining both approaches
    }
    printf("Hybrid result: %d\n", dynamicArray[0]);  // Output example
    free(dynamicArray);  // Free dynamic memory
    return 0;
}
